              "kommen - to come",
              "fahren — to drive / travel",
              "laufen — to run",
              "fliegen — to fly",
              "springen - to jump",
              "kriechen - to crawl",
              "schleichen — to creep",
              "hängen — to hang",
              "sich setzen - sit down",
              "sich stellen - to stand",
              "werfen — to throw",
